        "exam_code": "SU26 - C1RE",
        "question": "Làm sao để xóa bỏ triệt để, ngay lập tức các giai cấp, tầng lớp của cơ cấu xã hội - giai cấp trong thời kỳ quá độ lên chủ nghĩa xã hội?",
